template <int N>
void launch_fused_tile(const torch::Tensor& input, torch::Tensor& output) {
    constexpr int shared_bytes = N * (N + 1) * sizeof(float);
    fused_left_looking_tile<N><<<input.size(0), N, shared_bytes>>>(
        input.data_ptr<float>(), output.data_ptr<float>()
    );
}

torch::Tensor fused_tile_cholesky_cuda(
    torch::Tensor input, torch::Tensor output) {
    TORCH_CHECK(input.is_cuda(), "input must be CUDA");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(input.dim() == 3, "input must have shape (batch, n, n)");
    TORCH_CHECK(input.size(1) == input.size(2), "matrices must be square");
    TORCH_CHECK(output.is_cuda() && output.scalar_type() == torch::kFloat32,
                "output must be CUDA float32");
    TORCH_CHECK(output.is_contiguous() && output.sizes() == input.sizes(),
                "output must be a same-sized contiguous tensor");

    const int n = static_cast<int>(input.size(1));
    const c10::cuda::CUDAGuard device_guard(input.device());
    if (n == 32) {
        const int blocks = (static_cast<int>(input.size(0)) + 3) / 4;
        grouped_warp_cholesky_32<<<blocks, 128>>>(
            input.data_ptr<float>(), output.data_ptr<float>(), input.size(0)
        );
    } else if (n == 64) {
        launch_fused_tile<64>(input, output);
    } else if (n == 128) {
        constexpr int shared_bytes = 128 * 129 * sizeof(float);
        static const cudaError_t configured = cudaFuncSetAttribute(
            four_thread_rows_cholesky_128,
            cudaFuncAttributeMaxDynamicSharedMemorySize,
            shared_bytes
        );
        C10_CUDA_CHECK(configured);
        four_thread_rows_cholesky_128<<<input.size(0), 512, shared_bytes>>>(
            input.data_ptr<float>(), output.data_ptr<float>()
        );
    } else {
        TORCH_CHECK(false, "fused tile supports n=32, 64, or 128");
    }
    C10_CUDA_KERNEL_LAUNCH_CHECK();
