        packed_layout
        && cols % 4 == 0
        && panel.stride(0) % 4 == 0
        && panel.stride(1) % 4 == 0
        && converted.stride(0) % 4 == 0
        && converted.stride(1) % 4 == 0
        && source.stride(0) % 4 == 0
        && source.stride(1) % 4 == 0;
